ts\":[\"bundle\"],\"bundle\":\"plugin://plugin_connector_1p_689987207de08191979cf68eca2941c6/bundle\"}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-brand-check\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-brand-check\",\"title\":\"canva-brand-check\",\"description\":\"Check a Canva design against a brand kit and report where it diverges — off-palette colors, non-brand fonts, logo misuse, and off-tone copy. Read-only; makes no changes. Use when the user asks \\\"is this on brand\\\", \\\"check this against our brand kit\\\", \\\"do a brand review\\\", \\\"does this match our brand guidelines\\\", or \\\"brand-check my design\\\".\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49bfa7588191a223d8e77c07f4df\",\"skill_name\":\"canva-brand-check\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-branded-presentation\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-branded-presentation\",\"title\":\"canva-branded-presentation\",\"description\":\"Create on-brand Canva presentations from an outline or brief. Use when the user asks to create a branded presentation, make an on-brand deck, turn an outline into slides, or generate a presentation from a brief. Input can be text directly in the message, a Canva design ID, a reference to a Canva doc by name, or a Canva design link (e.g., https://www.canva.com/design/...).\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49bfe77c8191a00b184072390283\",\"skill_name\":\"canva-branded-presentation\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-bulk-create\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-bulk-create\",\"title\":\"canva-bulk-create\",\"description\":\"Bulk-create Canva designs from tabular data using a brand template with autofill fields, producing one design per row. Use when users say \\\"bulk create designs from this CSV\\\", \\\"generate one design per row\\\", \\\"create a design for each product\\\", \\\"batch generate from a template\\\", or \\\"autofill a template from a spreadsheet\\\". Accepts any tabular data source — uploaded files, pasted tables, JSON, or URLs.\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49c028048191919a8af8ec0a0569\",\"skill_name\":\"canva-bulk-create\",\"contents\":[],\"allow_implicit_invocation\":true}},{\"server\":\"codex_apps\",\"uri\":\"skill://plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-translate-design\",\"name\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba/canva-translate-design\",\"title\":\"canva-translate-design\",\"description\":\"Translate all text in a Canva design to another language, creating a translated copy. Faster than manually copying and editing each text box in Canva's editor. Use when users say \\\"translate my design to [language]\\\", \\\"make a Spanish/French/etc version\\\", or \\\"localize my Canva design\\\".\",\"mimeType\":\"mcp/skill\",\"_meta\":{\"plugin_id\":\"plugin_connector_68df33b1a2d081918778431a9cfca8ba\",\"plugin_name\":\"canva\",\"plugin_release_id\":\"pluginrel_d575a12fb6c08191947fd0c8515cde27\",\"plugin_release_skill_id\":\"pluginrsk_6a6c49c069008191adc16153cb86b667\",\"s